#define REPEAT_LIBRARY
#include "repeat.cpp"
int main(){init();setup();load();loadD();vector<vector<D>> old=move(ds);ds.resize(ts.size());for(int i=0;i<(int)ts.size();i++){auto&t=ts[i];string f=(t.name=="KPvKP"?"rep3_":"rep4_")+t.name+".bin";ds[i].resize(t.sz);ifstream in(f,ios::binary);in.read((char*)ds[i].data(),2ull*t.sz);assert(in.gcount()==2ull*t.sz);}long long audited=0,inf=0,improved=0;ofstream ex("infinite_repeat_examples.tsv");for(int id=0;id<(int)ts.size();id++){auto&t=ts[id];for(U a=0;a<(U)t.sz;a++){if(pc(t.v[a])!=0)continue;D d=ds[id][a],o=old[id][a];assert(d<=o&&d<=16);if(o<=8){assert(d==o);continue;}assert(t.v[a]==0);audited++;improved+=d<o;Pos p=dec(t,a);int best=o;bool cyc=four(id,p);if(cyc)best=min(best,8);moves(t,p,[&](Move m,Pos v){auto[j,q]=child(t,p,m,v);U b=enc(ts[j],q);if(pc(ts[j].v[b])==0)best=min(best,int(ds[j][b])+1);});assert(d==best);if(o!=INF)continue;inf++;int start=id;Pos cur=p;bool sw=false;vector<string> steps;for(int depth=0;;depth++){Cyc c;int k=getd(start,cur);if(k==8&&four(start,cur,&c)){string aa=uci(cur,c.a),bb=uci(cur,c.b);for(int j=0;j<2;j++){for(string u:{aa,bb,aa.substr(2)+aa.substr(0,2),bb.substr(2)+bb.substr(0,2)}){if(sw){u[1]='9'-u[1]+'0';u[3]='9'-u[3]+'0';}steps.push_back(u);}}break;}bool ok=false;auto&ct=ts[start];moves(ct,cur,[&](Move m,Pos v){if(ok)return;auto[j,q]=child(ct,cur,m,v);if(pc(ts[j].v[enc(ts[j],q)])||getd(j,q)!=k-1)return;string u=uci(cur,m);if(sw){u[1]='9'-u[1]+'0';u[3]='9'-u[3]+'0';}steps.push_back(u);sw^=q.turn!=1-cur.turn;cur=q;start=j;ok=true;});assert(ok&&depth<16);}assert((int)steps.size()==d);ex<<t.name<<'\t'<<a<<'\t'<<fen(t,p)<<'\t'<<d<<'\t';for(auto&s:steps)ex<<s<<' ';ex<<'\n';}}cout<<"AUDIT repeat "<<audited<<" high, "<<improved<<" improved, "<<inf<<" infinite D0 certificates\n";}
